const bar=(v,c)=>`<div class="bar"><span style="width:${C(v,0,100)}%;background:${c||'var(--gr)'}"></span></div>`;
const atc=v=>v>=75?'var(--gr)':v>=60?'#a3e635':v>=45?'var(--yl)':'var(--or)';
const ATC={speed:'#3ddc84',shoot:'#ffd400',pass:'#a78bfa',dribble:'#3b7bff',defense:'#ff5a5f',physical:'#22d3ee'};
const esc=t=>String(t).replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
/* ---- partida: painel de escolhas e lances ---- */
function showMatch(on){$('match').classList.toggle('hidden',!on);$('nav').classList.toggle('hidden',on);document.querySelector('header').classList.toggle('hidden',on);
 ['home','train','play','career','mkt'].forEach(id=>$(id).classList.toggle('hidden',on||id!==curPg))}
function updLog(){const l=$('mlog');if(!l||!M)return;l.innerHTML=[...M.log].reverse().map(e=>`<p><i>${e[0]}'</i><span class="${e[2]>0?'gr':e[2]<0?'rd':''}">${esc(e[1])}</span></p>`).join('')||'<p class="mt"><i></i><span>Nenhum lance ainda.</span></p>'}
function ui(){const v=$('mv');if(!M)return;updLog();const ph=M.ph;
 if(ph==='pick'||ph==='sop'){const mt=M.mt,gs=gameState(),sit=M.sit||mt;
  v.innerHTML=`<div class="sit"><b>${sit.t||''}</b><span>${sit.d||''}</span>${gs&&ph==='pick'?`<i>${gs}</i>`:''}</div><p class="q">${mt.q||SC[mt.r]}</p><div class="acts">${mt.opts.map((o,i)=>{const tg=mt.nt?null:sitTag(sitMul(i));
   return`<button data-o="${i}">${icon(o[1])}<span><b>${i+1}. ${o[0]}</b>${tg?` <span class="tag ${tg[1]}">${tg[0]}</span>`:''}<br><small>${o[3]}</small>${mt.nt?'':`<br><small class="yl">${AN[o[1]]} ${S.attrs[o[1]]}</small>`}</span></button>`}).join('')}</div>`}
 else if(ph==='time'||ph==='sot')v.innerHTML=`<p class="q">Pare o marcador na faixa verde. Centro dourado = perfeito!</p><p class="mt" style="text-align:center">Faixa ${Math.round(M.z.w*100)}% · velocidade ${M.z.sp>5.6?'alta':M.z.sp>4.4?'média':'baixa'} · fôlego ${Math.round(M.sta)}</p><div id="tb"><i id="zn" style="left:${(M.z.c-M.z.w/2)*100}%;width:${M.z.w*100}%"><i id="zp"></i></i><i id="cur"></i></div><button class="go big" id="act" style="width:100%">AGORA!</button>`;
 else if(ph==='end')v.innerHTML='';else v.innerHTML=`<p class="q">${esc(M.msg)}</p>`;
 document.querySelectorAll('[data-o]').forEach(b=>b.onclick=()=>pick(+b.dataset.o));if($('act'))$('act').onpointerdown=tap}
function gameState(){if(!M)return '';const d=M.s[0]-M.s[1];if(M.min>=75&&d<0)return 'PRECISA DO GOL!';if(M.min>=75&&d===0)return 'JOGO EMPATADO NO FIM';if(M.min>=75&&d===1)return 'SEGURE O RESULTADO!';return ''}
/* ---- navegação ---- */
const PG=['home','train','play','career','mkt'],PGN=['Início','Treino','Jogo','Carreira','Mercado'],PGI=['home','train','play','career','mkt'];
$('nav').innerHTML=PG.map((p,i)=>`<button data-p="${p}" class="${i?'':'on'}">${icon(PGI[i])}<span>${PGN[i]}</span></button>`).join('');
let curPg='home';const SUB={play:'cal',career:'perfil',mkt:'ofertas'};
function page(p,sub){if(M)return;if(sub)SUB[p]=sub;document.querySelectorAll('section').forEach(s=>{if(s.id==='match')return;const on=s.id===p;s.classList.toggle('hidden',!on);if(on&&p!==curPg){s.classList.remove('enter');void s.offsetWidth;s.classList.add('enter')}});
 document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('on',b.dataset.p===p));curPg=p;if(sub)rd();trainAnim(p==='train')}
document.querySelectorAll('nav button').forEach(b=>b.onclick=()=>{SND.ui(480);page(b.dataset.p)});
