const CR={step:0,name:'Gabriel Silva',num:10,foot:'Direito',pos:'Meia-atacante',style:'Armador',pers:'Profissional',sk:2,hs:0,hc:0,club:0};
function openCreate(){Object.assign(CR,{step:0});const l=lookOf('u'+CR.name);CR.sk=l.sk;CR.hs=l.hs;CR.hc=l.hc;$('mod').classList.remove('hidden');wiz()}
function wiz(){const w=$('wiz'),st=CR.step,P=['Meia-atacante','Atacante','Ponta-direita','Ponta-esquerda','Volante','Zagueiro','Lateral','Goleiro'];if(!STY_POS(CR.pos).includes(CR.style))CR.style=STY_POS(CR.pos)[0];
 let h=`<h2>${icon('career')} Criar atleta · passo ${st+1} de 4</h2><div class="wiz">${[0,1,2,3].map(i=>`<i class="${i<=st?'on':''}"></i>`).join('')}</div><div class="cre"><div>`;
 if(st===0)h+=`<label for="nn">Nome</label><input id="nn" maxlength="22" value="${esc(CR.name)}"><label for="nu">Camisa</label><input id="nu" type="number" min="1" max="99" value="${CR.num}"><label for="nf">Pé dominante</label><select id="nf">${['Direito','Esquerdo','Ambos'].map(f=>`<option ${f===CR.foot?'selected':''}>${f}</option>`).join('')}</select>`;
 if(st===1)h+=`<label>Posição</label><div class="cards3">${P.map(p=>`<button data-cp="${p}" class="${p===CR.pos?'on':''}"><b>${PAB[p]}</b>${p}</button>`).join('')}</div><label>Estilo de jogo</label><div class="cards3">${STY_POS(CR.pos).map(s=>`<button data-cs="${s}" class="${s===CR.style?'on':''}"><b>${s}</b><small>${STY[s].d}</small></button>`).join('')}</div>
  <label>Personalidade</label><div class="cards3">${Object.keys(PERS).map(p=>`<button data-cq="${p}" class="${p===CR.pers?'on':''}"><b>${p}</b><small>${PERS[p]}</small></button>`).join('')}</div>`;
 if(st===2)h+=`<label>Tom de pele</label><div class="sw">${SKIN.map((s,i)=>`<button data-sk="${i}" class="${i===CR.sk?'on':''}" style="background:${s[0]}" aria-label="Tom ${i+1}"></button>`).join('')}</div><label for="nh">Cabelo</label><select id="nh">${HAIRS.map((x,i)=>`<option value="${i}" ${i===CR.hs?'selected':''}>${x}</option>`).join('')}</select><label>Cor do cabelo</label><div class="sw">${HAIRC.map((x,i)=>`<button data-hc="${i}" class="${i===CR.hc?'on':''}" style="background:${x}" aria-label="Cor ${i+1}"></button>`).join('')}</div>`;
 if(st===3)h+=`<label>Clube da base</label><div class="clubs">${[0,1,2].map(i=>`<button data-cc="${i}" class="${i===CR.club?'on':''}"><img src="${kitBadge(i)}" alt="">${CL[i].n}</button>`).join('')}</div><p class="mt">Você começa no Sub-17, com 16 anos. Seu potencial será revelado aos poucos pelos olheiros.</p>`;
 h+=`</div><canvas id="cp" width="64" height="64"></canvas></div><p></p><div class="toolbar"><button id="wb" ${st?'':'disabled'}>Voltar</button><button class="go" id="wn" style="flex:1">${st<3?'Próximo':'Começar carreira'}</button><button id="wx">Cancelar</button></div>`;
 w.innerHTML=h;const pv=()=>{const x=$('cp').getContext('2d'),l=lookOf('u'+CR.name);l.sk=CR.sk;l.hs=CR.hs;l.hc=CR.hc;x.clearRect(0,0,64,64);portrait(x,0,0,4,l,kitOf(CR.club),CR.num,{ex:1,gk:CR.pos==='Goleiro'})};
 const rd0=()=>{if($('nn'))CR.name=$('nn').value.trim()||'Jogador';if($('nu'))CR.num=C(+$('nu').value||10,1,99);if($('nf'))CR.foot=$('nf').value;if($('nh'))CR.hs=+$('nh').value};
 w.querySelectorAll('input,select').forEach(e=>e.addEventListener('input',()=>{rd0();pv()}));
 const bind=(a,k,num)=>w.querySelectorAll(`[data-${a}]`).forEach(b=>b.onclick=()=>{CR[k]=num?+b.dataset[a]:b.dataset[a];wiz()});bind('cp','pos');bind('cs','style');bind('cq','pers');bind('sk','sk',1);bind('hc','hc',1);bind('cc','club',1);
 $('wb').onclick=()=>{rd0();CR.step--;wiz()};$('wx').onclick=()=>{$('mod').classList.add('hidden');openMenu()};$('wn').onclick=()=>{rd0();if(st<3){CR.step++;wiz()}else createCareer()};pv()}
function createCareer(){S=def();Object.assign(S,{name:CR.name,pos:CR.pos,foot:CR.foot,num:CR.num,style:CR.style,pers:CR.pers,club:CR.club,made:1,look:{sk:CR.sk,hs:CR.hs,hc:CR.hc}});
 const a=S.attrs,b=POS[S.pos];for(const k in b)a[k]=C(a[k]+b[k],20,99);for(const k of(STY[S.style]||{a:[]}).a)a[k]=C(a[k]+2,20,99);S.pot=C(68+((RN()*24)|0),68,94);S.sal=CL[S.club].s;S.con={end:S.season+2,loan:null};
 buildSeason();news('Bem-vindo à base!',`Você assinou com o ${clubName(S.club)} até ${S.con.end}. O treinador quer ver você em campo.`,'voce','star');
 $('mod').classList.add('hidden');SND.whistle(1);sv();rd();page('home');scrollTo(0,0)}
